import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu'
import { texture as textureNode } from 'three/tsl'

export default function createNode(config, ctx) {
  // -- geometry sized to the atlas region aspect ratio (512x320 = 1.6:1) --
  const aspect = 512 / 320
  const geometry = new PlaneGeometry(aspect, 1)

  // -- load texture and set UV sub‑region from atlas source rect --
  const texture = ctx.textureLoader.load(config.imageUrl)
  if (texture.image) {
    const imgW = texture.image.width
    const imgH = texture.image.height
    const srcW = 512
    const srcH = 320
    texture.repeat.set(srcW / imgW, srcH / imgH)
    texture.offset.set(0, 1 - srcH / imgH) // top‑left origin → bottom‑left UV
  }

  // -- material with the sub‑region texture --
  const material = new MeshBasicNodeMaterial({
    map: textureNode(texture),
    transparent: true,
    side: 2, // DoubleSide
  })

  // -- build the mesh --
  const mesh = new Mesh(geometry, material)
  mesh.position.set(
    config.scenePosition.x ?? 0,
    config.scenePosition.y ?? 0,
    config.scenePosition.z ?? 0
  )
  mesh.rotation.set(
    config.scenePosition.rotation?.x ?? 0,
    config.scenePosition.rotation?.y ?? 0,
    config.scenePosition.rotation?.z ?? 0
  )
  if (config.scenePosition.scale) {
    mesh.scale.set(
      config.scenePosition.scale.x ?? 1,
      config.scenePosition.scale.y ?? 1,
      config.scenePosition.scale.z ?? 1
    )
  }

  // -- empty handlers (no interactions) --
  mesh.userData.handlers = {}

  // -- cleanup --
  mesh.userData.cleanup = () => {
    geometry.dispose()
    material.dispose()
    // texture is cached by ctx.textureLoader – do not dispose globally
  }

  return mesh
}
